package com.monti.servecoach.core

import org.junit.Assert.assertTrue
import org.junit.Test
import kotlin.math.hypot

/**
 * How far the ball really is from where [Predict] says it will be.
 *
 * The live-window design rests on this number. The window has to be cut before the tracker has
 * said where the ball is, so the margin it carries is whatever the prediction misses by, and the
 * margin is what the chip has to read back inside the 4.17 ms a frame gets at 240 a second.
 *
 * The tracks are every flight of the four recorded sessions with twelve points or more --
 * seventeen of them, 618 points, in whole-picture pixels at the capture's own frame numbers.
 * Real serves, with the tracker's noise and its gaps, which is the point: a smooth invented
 * flight would say the prediction is perfect and prove nothing.
 */
class PredictTest {
    private fun points(a: FloatArray) = (a.indices step 4).map {
        floatArrayOf(a[it], a[it + 1], a[it + 2], a[it + 3])
    }

    /**
     * The miss at every point of every track, predicting from points at least [lag] frames old.
     *
     * Points the size of a paddle are not scored. At the hit the ball merges with the bat and the
     * tracker reports a blob two or three times too big, somewhere between the two; asking how
     * far the prediction is from *that* is not the question, because the window's job is to hold
     * the ball. Those points are left out of the prediction for the same reason, in Predict.
     */
    private fun misses(lag: Float, use: Int = 3): List<Double> {
        val out = ArrayList<Double>()
        for ((_, flat) in TRACKS) {
            val t = points(flat)
            val rs = t.map { it[3] }.sorted()
            val rMed = rs[rs.size / 2]
            for (p in t) {
                if (p[3] < 0.5f * rMed || p[3] > 1.5f * rMed) continue
                val got = Predict.at(t, p[0], lag, use) ?: continue
                out.add(hypot((got[0] - p[1]).toDouble(), (got[1] - p[2]).toDouble()))
            }
        }
        return out.sorted()
    }

    private fun report(name: String, m: List<Double>) =
        "%s: %d points, median %.1f px, 90th %.1f, worst %.1f".format(name, m.size, m[m.size / 2], m[(m.size * 9) / 10], m.last())

    @Test fun `a window cut two frames late still holds the ball`() {
        val m = misses(2f)
        println(report("lag 2", m))
        // measurePole needs 2.6r round the ball for its white reference -- about 47 px for a
        // ball of 18 -- so a 192 px square leaves 96 either way and the miss has to stay inside
        // that. Measured worst over the seventeen flights: 45 px, at a four-frame gap in a track.
        assertTrue("the usual miss must be small. " + report("lag 2", m), m[m.size / 2] < 10)
        assertTrue("the worst miss must fit the margin. " + report("lag 2", m), m.last() < 50)
    }

    @Test fun `falling further behind is what breaks it`() {
        // The readback is two frames late by design, and a 192 px window leaves 96 px of margin
        // round the 47 the measurement needs -- twice the 45 px the prediction misses by at that
        // lag. Four frames behind, the worst miss is about 97 px and the ball starts leaving the
        // window. So the lag is the thing to hold, not the window size: it is cheaper to keep the
        // readback prompt than to read back a bigger square every frame.
        for (lag in listOf(4f, 6f)) {
            val m = misses(lag)
            println(report("lag ${lag.toInt()}", m))
            assertTrue("the middle of the distribution must stay tight. " + report("lag ${lag.toInt()}", m), m[m.size / 2] < 12)
        }
        assertTrue("two frames behind must be well inside the margin", misses(2f).last() < 50)
        assertTrue("four frames behind must not be", misses(4f).last() > 50)
    }

    @Test fun `three points beat five`() {
        // More points means a longer baseline to extrapolate from, and on a flight that curves
        // that is worse, not better: five points miss by 102 px at worst where three miss by 45.
        // The middle of the distribution improves slightly, which is what makes it tempting.
        val three = misses(2f, 3)
        val five = misses(2f, 5)
        println(report("3 points", three)); println(report("5 points", five))
        assertTrue("three points must have the better worst case: ${three.last()} against ${five.last()}",
            three.last() < five.last())
    }

    @Test fun `it says nothing when it has nothing`() {
        val t = points(TRACKS[0].second)
        assertTrue("there is no prediction before any point is old enough", Predict.at(t, t[0][0], 2f) == null)
        assertTrue("nor from a single point", Predict.at(t, t[1][0], 2f) == null)
    }

    @Test fun `it holds its tongue for only the first few frames`() {
        var asked = 0; var given = 0
        for ((_, flat) in TRACKS) {
            val t = points(flat)
            for (p in t) { asked++; if (Predict.at(t, p[0], 2f) != null) given++ }
        }
        val share = given.toDouble() / asked
        println("a window is placed for %.0f%% of tracked frames".format(100 * share))
        assertTrue("most frames must get a window, got %.0f%%".format(100 * share), share > 0.85)
    }

